package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithClaim {
    public void respond(@Val Claim claim, ClaimLogRepository logs, ClaimLockRepository locks,
            ClaimRepository repository, ClaimCommentRepository comments, ClaimLineRepository lines,
            SettleBatchRepository batches, ObjectResponse<ClaimResponse> response) {
        response.send(ClaimResponse.from(claim, logs.find(claim.sheetId(), claim.id()),
                locks.lockedBy(claim.sheetId(), claim.id()),
                repository.lateEntry(claim.sheetId(), claim.id()),
                repository.reminded(claim.sheetId(), claim.id()),
                repository.ref(claim.sheetId(), claim.id()),
                repository.tags(claim.sheetId(), claim.id()),
                repository.voidReason(claim.sheetId(), claim.id()),
                comments.find(claim.sheetId(), claim.id()),
                batches.batch(claim.sheetId(), claim.id()),
                lines.find(claim.sheetId(), claim.id())));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class SaveClaim {
    public void save(@Val Claim claim, ClaimRepository repository, Out<Claim> saved) {
        saved.set(repository.save(claim));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadClaim {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") long claimId,
            ClaimRepository repository, Out<Claim> claim) throws ClaimNotFoundException {
        Claim found = repository.find(sheetId, claimId);
        if (found == null) {
            throw new ClaimNotFoundException(claimId);
        }
        claim.set(found);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Moves the claim to its new date, keeping its due-by, its number and any statement figure. Its period is the one
 * containing its due-by, so a re-date never moves it to another period (nor another period numbering sequence).
 */
public class RedateClaim {
    public void redate(@Val Claim claim, @Val Redating redating, ClaimRepository repository, Out<Claim> redated) {
        Claim moved = claim.redateTo(redating.to(), claim.number());
        repository.redate(moved);
        redated.set(moved);
    }
}

